import pandas as pd
df = pd.read_csv('user_data.csv')
print("Kolom tersedia:", df.columns.tolist())
df['order_date'] = pd.to_datetime(df['order_date'] if 'order_date' in df.columns else df['date'])
df_nov = df[(df['order_date'] >= '2025-11-01') & (df['order_date'] <= '2025-11-30')]

# Cek apakah ada kolom nama produk yang lebih spesifik
for col in df.columns:
    if 'name' in col.lower() or 'product' in col.lower() or 'item' in col.lower():
        print(f"\n--- Top 5 untuk kolom {col} ---")
        if 'quantity' in df.columns:
            print(df_nov.groupby(col)['quantity'].sum().reset_index().sort_values(by='quantity', ascending=False).head(5).to_string(index=False))
        else:
            print(df_nov[col].value_counts().head(5))
